.replay-button { text-decoration: none; display: inline-flex; vertical-align: middle; margin: 3px; }


.replay-button svg circle { fill: #3f3f3f; stroke: #202020; }

.replay-button svg path { fill: #ab997e; }

.mobile .replay-button svg { width: 50px; height: 50px; }
.replay-button svg { width: 50px; height: 50px; }

svg > text { fill: #ab997e !important; }
svg > path { stroke: #b29584 !important; }
svg > circle[r="5"] { fill: #ab997e !important; }
svg > circle[r="3.25"] { fill: #2d2d2d !important; }
:root { --fg-subtle: #8a7c6a; }
